def sum_common_divisors(a, b):
    """
    Returns the sum of all common divisors of two given numbers.
    """
    if a == 0 or b == 0:
        return 0

    # Find the greatest common divisor (GCD)
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Find all common divisors by iterating up to the smaller number
    smaller = min(a, b)
    common_divisors = []
    for i in range(1, smaller + 1):
        if a % i == 0 and b % i == 0:
            common_divisors.append(i)

    return sum(common_divisors)
