fn make_palindrome(string: String) -> String {
    let n = string.len();
    let mut i = 0;
    let mut j = n - 1;
    let mut palindromic_suffix_len = 0;

    while i < j {
        if string[i] == string[j] {
            palindromic_suffix_len += 1;
            i += 1;
            j -= 1;
        } else {
            break;
        }
    }

    let mut prefix_len = palindromic_suffix_len;
    let mut prefix = String::new();
    let mut suffix = String::new();

    while i < j {
        prefix.push(string[i]);
        suffix.push(string[j]);
        i += 1;
        j -= 1;
    }

    let mut result = String::new();
    result.push_str(&string[..palindromic_suffix_len]);
    result.push_str(&suffix);
    result.push_str(&prefix);
    result.push_str(&string[palindromic_suffix_len..]);

    result
}

