fn decimal_to_binary(decimal: isize) -> String {
    let mut result = String::new();
    result.push_str("db");

    if decimal == 0 {
        result.push_str("db");
    } else {
        let mut num = decimal;
        while num > 0 {
            let remainder = num % 2;
            num /= 2;
            result.push_str(if remainder == 0 { "0" } else { "1" });
        }
    }

    result.push_str("db");
    result
}

fn sum_product(numbers: Vec<isize>) -> (isize, isize) {
    let mut sum: isize = 0;
    let mut product: isize = 1;

    for &num in &numbers {
        sum += num;
        product *= num;
    }

    (sum, product)
}

