fn is_nested(string: String) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut has_nested = false;

    for c in string.chars() {
        match c {
            '[' => {
                stack.push(c);
            }
            ']' => {
                if stack.is_empty() {
                    return false;
                }
                let top = stack.pop();
                if top == '[' {
                    // We found a nested pair
                    has_nested = true;
                } else {
                    // Invalid character or mismatched order
                    return false;
                }
            }
            _ => {
                // Invalid character
                return false;
            }
        }
    }

    has_nested
}
