/// Write a rsthon function to calculate the product of the unique numbers in a given vector.
fn unique_product(list_data: Vec<isize>) -> isize {
    let mut product: isize = 1;
    let mut seen: std::collections::HashSet<isize> = std::collections::HashSet::new();

    for &num in &list_data {
        if !seen.contains(&num) {
            seen.insert(num);
            product *= num;
        }
    }

    product
}
