fn capital_words_spaces(str1: String) -> String {
    let mut result = String::new();
    let mut last_was_space = false;

    for (i, c) in str1.chars().enumerate() {
        if c.is_whitespace() {
            if !last_was_space {
                result.push(' ');
            }
            last_was_space = true;
            continue;
        }

        if c.is_uppercase() {
            if !last_was_space {
                result.push(' ');
            }
            last_was_space = true;
        }

        result.push(c);
        last_was_space = false;
    }

    result
}

