fn f(n: isize) -> Vec<isize> {
    let mut result = Vec::with_capacity(n + 1);
    let mut i = 1;
    let mut factorial = 1;

    while i <= n {
        if i % 2 == 0 {
            result.push(factorial);
        } else {
            let sum = (i * (i + 1)) / 2;
            result.push(sum);
        }
        i += 1;
        factorial *= i;
    }

    result
}

