fn get_total_number_of_sequences(m: isize, n: isize) -> isize {
    if n <= 0 {
        return 0;
    }
    if m <= 0 {
        return 0;
    }

    let mut count = 1; // For n = 1, there is only 1 sequence: [m]
    let mut prev = m;

    for _ in 1..n {
        let mut next = 0;
        for i in 1..=prev {
            if i >= 2 * prev {
                break;
            }
            next = i;
        }
        prev = next;
        count += 1;
    }

    count
}

