/// Write a function to find the longest common subsequence for the given three string sequence.
/// https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/
fn lcs_of_three(X: String, Y: String, Z: String) -> isize {
    let m = X.len();
    let n = Y.len();
    let k = Z.len();

    // Create a 3D DP table where dp[i][j][l] stores the LCS length of X[0..i], Y[0..j], Z[0..l]
    let mut dp = vec![vec![vec![0usize; k + 1]; n + 1]; m + 1];

    // Fill the DP table
    for i in 1..=m {
        for j in 1..=n {
            for l in 1..=k {
                if X[i - 1] == Z[l - 1] {
                    dp[i][j][l] = 1 + dp[i - 1][j][l - 1];
                } else {
                    dp[i][j][l] = dp[i - 1][j][l];
                    dp[i][j][l] = dp[i][j - 1][l];
                    dp[i][j][l] = dp[i][j][l - 1];
                }
            }
        }
    }

    // The result is the value at dp[m][n][k]
    dp[m][n][k]
}
