fn first_non_repeating_character(str1: String) -> Option<String> {
    let mut char_count: std::collections::HashMap<char, usize> = std::collections::HashMap::new();
    let mut first_non_repeating: Option<char> = None;

    for c in str1.chars() {
        *char_count.entry(c).or_insert(0) += 1;
        if *char_count.get(&c).unwrap() == 1 {
            first_non_repeating = Some(c);
            break;
        }
    }

    first_non_repeating
}
